// @ts-ignore
const fetch = global.get('fetch');

async function fetchCfg() {
  const cached = flow.get('cfgCache');
  if (cached && (Date.now() - cached.at) < 10000) return cached.cfg;
  const base = env.get('RADIO_PROXY_URL') || 'http://radio-proxy:8091';
  const res = await fetch(base + '/config');
  if (!res.ok) throw new Error('fetchCfg ' + res.status);
  const cfg = await res.json();
  flow.set('cfgCache', { at: Date.now(), cfg });
  return cfg;
}

function resolveTarget(cfg, target) {
  if (!target) throw new Error('Missing target');
  if (target.startsWith('speaker:')) {
    const id = target.slice(8);
    const speaker = (cfg.speakers || {})[id];
    if (!speaker) throw new Error('Unknown speaker ' + id);
    return { type: 'speaker', id, speaker };
  }
  if (target.startsWith('zone:')) {
    const id = target.slice(5);
    const zone = (cfg.zones || {})[id];
    if (!zone) throw new Error('Unknown zone ' + id);
    const masterId = zone.master;
    const speaker = (cfg.speakers || {})[masterId];
    if (!speaker) throw new Error('Unknown zone master ' + masterId);
    return { type: 'zone', id, zone, speaker, speakerId: masterId };
  }
  throw new Error('Target must start with speaker: or zone:');
}

function clampVolume(raw) {
  const volume = Math.max(0, Math.min(100, Math.round(Number(raw))));
  if (!Number.isFinite(volume)) throw new Error('volume must be a number from 0 to 100');
  return volume;
}

function tag(text, name) {
  const m = String(text).match(new RegExp('<' + name + '>([^<]*)</' + name + '>'));
  return m ? m[1] : '';
}

function parseVolumeXml(text) {
  const targetvolume = Number(tag(text, 'targetvolume'));
  const actualvolume = Number(tag(text, 'actualvolume'));
  return {
    targetvolume: Number.isFinite(targetvolume) ? targetvolume : null,
    actualvolume: Number.isFinite(actualvolume) ? actualvolume : null,
    muteenabled: tag(text, 'muteenabled') === 'true',
    response: text,
  };
}

async function getSpeakerVolume(id, speaker) {
  const res = await fetch('http://' + speaker.ip + ':8090/volume', { method: 'GET' });
  const text = await res.text();
  if (!res.ok) throw new Error('volume read failed on ' + speaker.ip + ': ' + res.status + ': ' + text);
  return {
    ok: true,
    id,
    name: speaker.name || id,
    ip: speaker.ip,
    ...parseVolumeXml(text),
  };
}

async function setSpeakerVolume(id, speaker, volume) {
  const res = await fetch('http://' + speaker.ip + ':8090/volume', {
    method: 'POST',
    headers: { 'Content-Type': 'application/xml' },
    body: '<volume>' + volume + '</volume>'
  });
  const text = await res.text();
  if (!res.ok) throw new Error('volume failed on ' + speaker.ip + ': ' + res.status + ': ' + text);
  return {
    ok: true,
    id,
    name: speaker.name || id,
    ip: speaker.ip,
    volume,
    response: text,
  };
}

(async () => {
  try {
    const cfg = await fetchCfg();
    const body = msg.payload || {};
    const targetName = body.target;
    const target = resolveTarget(cfg, targetName);
    const speakerId = target.type === 'speaker' ? target.id : target.speakerId;
    const volume = clampVolume(body.volume);
    const result = await setSpeakerVolume(speakerId, target.speaker, volume);
    msg.payload = { ok: true, target: targetName, speaker: result.name, volume, response: result.response };
    node.send(msg);
  } catch (e) {
    msg.statusCode = 500;
    msg.payload = { ok: false, error: e.message || String(e) };
    node.send(msg);
  }
})();
return null;

